        ["Show Blizzard's floating destination marker and distance for the tracked quest or map pin. This changes the game's shared navigation setting."] = "Affiche le marqueur flottant et la distance pour la quête ou le marqueur suivi. Modifie le paramètre de navigation partagé du jeu.",
        ["Hold Shift at an NPC to skip automation once."] = "Maintenez Shift sur un PNJ pour ignorer l’automatisation une fois.",
        ["Show in-world destination marker"] = "Afficher le marqueur de destination dans le monde",
        ["Auto-turn in quests"] = "Remettre les quêtes automatiquement",
        ["Accept quests automatically when you talk to an NPC. Hold Shift to skip."] = "Accepte automatiquement les quêtes lorsque vous parlez à un PNJ. Maintenez Maj pour ignorer l’automatisation.",
        ["Limit auto-accept quest level"] = "Limiter le niveau de quête d'acceptation automatique",
        ["Only auto-accept quests within the level range around your level. Unknown quest levels are left for manual acceptance."] = "N'accepte automatiquement que les quêtes dans la plage de niveaux autour de votre niveau. Les niveaux de quête inconnus sont laissés pour acceptation manuelle.",
        ["Auto-accept quest levels: yours %+d to %+d"] = "Niveaux de quête acceptés automatiquement : le vôtre %+d à %+d",
        ["Don't auto-accept grey quests"] = "Ne pas accepter automatiquement les quêtes grises",
        ["Skip quests the game shows as grey (trivial) for your level. You can still accept them manually."] = "Ignore les quêtes que le jeu affiche en gris (triviales) pour votre niveau. Vous pouvez toujours les accepter manuellement.",
        ["Turn in completed quests automatically. Does not pick when there are multiple rewards. Hold Shift to skip."] = "Remet automatiquement les quêtes terminées. Ne choisit pas lorsqu’il y a plusieurs récompenses. Maintenez Maj pour ignorer l’automatisation.",
        ["Debug tooltips"] = "Info-bulles de débogage",
        ["Show quest IDs, NPC IDs, map coordinates, and pin-parent diagnostics on hover."] = "Afficher les identifiants de quête, les identifiants de PNJ, les coordonnées de la carte et les diagnostics des broches parents en survol.",
        ["Hide quest tracker in combat"] = "Masquer le suivi de quête pendant le combat",
        ["Quest"] = "Quête",
        ["Reset hidden quest pins"] = "Réinitialiser les marqueurs de quête cachées",
        ["Show quest start pins"] = "Afficher les marqueurs de début de quête",
        ["Quest giver NPC "] = "PNJ donneur de quête ",
        ["Blizzard Map Pins"] = "Épingles de carte Blizzard",
        ["%d hidden on this character. Shift-click a map pin to hide it."] = "%d caché sur ce personnage. Maj-cliquez sur une marqueur de carte pour la masquer.",
        ["Type /fqp for commands and troubleshooting."] = "Tapez /fqp pour les commandes et le dépannage.",
        ["%d possible spawn locations"] = "%d emplacements d’apparition possibles",
        ["Show every quest pin you hid with Shift-click on this character. Other characters keep their hidden pins."] = "Montrez chaque marqueur de quête que vous avez cachée avec Shift-clic sur ce personnage. Les autres personnages gardent leurs marqueurs cachées.",
        ["Makes the default objective tracker transparent while you are in combat and restores its opacity afterward. Keeps your manual collapse setting."] = "Rend le suivi d'objectif par défaut transparent pendant que vous êtes en combat et restaure son opacité par la suite. Conserve votre paramètre de réduction manuelle.",
        ["Copy Wowhead URL"] = "Copier l'URL Wowhead",
        ["TomTom could not create this waypoint."] = "TomTom n'a pas pu créer ce waypoint.",
        ["Click to track this quest start."] = "Cliquez pour suivre le début de cette quête.",
        ["Quest %d (title unavailable)"] = "Quête %d (titre indisponible)",
        ["Shift-click to hide this marker."] = "Maj-clic pour masquer ce marqueur.",
        ["TomTom is not loaded. Choose Blizzard Map Pins or enable TomTom."] = "TomTom n’est pas chargé. Choisissez les marqueurs de carte Blizzard ou activez TomTom.",
        ["Blizzard quest tracking is unavailable on this client."] = "Le suivi des quêtes Blizzard n'est pas disponible sur ce client.",
        ["  /fqp clear    Clear the addon waypoint"] = "  /fqp clear Effacer le waypoint du module complémentaire",
        ["  /fqp on       Enable quest-start pins"] = "  /fqp on Activer les marqueurs de démarrage de quête",
        ["Blizzard Map Pins are unavailable on this client. TomTom can be selected in options."] = "Les marqueurs de carte Blizzard ne sont pas disponibles sur ce client. TomTom peut être sélectionné dans les options.",
        ["Commands:"] = "Commandes :",
        ["  /fqp highlevel <%d-%d> Hide quests this many levels above you (default %d means show all)"] = "  /fqp highlevel <%d-%d> Masquer les quêtes à autant de niveaux au-dessus de vous (%d par défaut signifie tout afficher)",
        ["  /fqp trivial  Toggle low-level/trivial pins (off by default)"] = "  /fqp trivial Basculer les broches de bas niveau/triviales (désactivées par défaut)",
        ["  /fqp trivial <%d-%d> Hide quests this many levels below you (default %d)"] = "  /fqp trivial <%d-%d> Masquer les quêtes à autant de niveaux en dessous de vous (%d par défaut)",
        ["  /fqp track <id> Track a quest start, objective, or turn-in"] = "  /fqp track <id> Suivre le début, l'objectif ou l'arrivée d'une quête",
        ["  /fqp accept   Toggle auto-accept quests"] = "  /fqp accept Activer ou désactiver l’acceptation automatique des quêtes",
        ["  /fqp off      Disable quest-start pins"] = "  /fqp off Désactiver les broches de démarrage de quête",
        ["  /fqp repeatable Toggle repeatable quest pins (on by default)"] = "  /fqp repeatable Activer/désactiver les marqueurs de quête répétables (activées par défaut)",
        ["  /fqp books    Toggle collectible book quest pins (off by default)"] = "  /fqp books    Activer/désactiver les marqueurs des quêtes de livres de collection (désactivés par défaut)",
        ["  /fqp seasonal Toggle holiday/seasonal pins (off by default)"] = "  /fqp seasonal Basculer les marqueurs de vacances/saisonnières (désactivées par défaut)",
        ["  /fqp spawns   Toggle grouped spawn pins (on by default)"] = "  /fqp spawns Activer/désactiver les broches d'apparition groupées (activées par défaut)",
        ["  /fqp wareffort Toggle AQ war effort pins in capitals (off by default)"] = "  /fqp wareffort Activer ou désactiver les marqueurs de l'effort de guerre d'AQ dans les capitales (désactivés par défaut)",
        ["  /fqp wareffort always Always show AQ war effort pins"] = "  /fqp wareffort always Toujours afficher les marqueurs de l’effort de guerre d’AQ",
        ["  /fqp hidden   List quest pins hidden with Shift-click on this character"] = "  /fqp hidden Liste les marqueurs de quête cachées avec Shift-clic sur ce personnage",
        ["  /fqp npctooltip Toggle quest accept and ready turn-in lines on NPC mouseover"] = "  /fqp npctooltip Activer ou désactiver les quêtes disponibles et prêtes à rendre dans les info-bulles des PNJ",
        ["  /fqp nameplates Toggle quest icons on nameplates (on by default)"] = "  /fqp nameplates Activer ou désactiver les icônes de quête sur les plaques de nom (activé par défaut)",
        ["  /fqp nameplatedebug Print visible nameplate icon state"] = "  /fqp nameplatedebug Afficher l'état des icônes des plaques de nom visibles",
        ["Nameplates module not loaded."] = "Module des plaques de nom non chargé.",
        ["  /fqp debug    Toggle debug tooltips and chat diagnostics"] = "  /fqp debug Basculer les info-bulles de débogage et les diagnostics de chat",
        ["  /fqp unhide <id|all> Restore one or all hidden quest pins"] = "  /fqp unhide <id|all> Restaurer un ou tous les repères de quête cachés",
        ["  /fqp turnin   Toggle auto-turn in quests"] = "  /fqp turnin   Activer ou désactiver la remise automatique des quêtes",
        ["  /fqp refresh  Rebuild pins on the current map"] = "  /fqp refresh Reconstruire les repères sur la carte actuelle",
        ["  /fqp settings Print saved option values (debug)"] = "  /fqp settings Imprimer les valeurs des options enregistrées (débogage)",
        ["  /fqp stats    Print database and pin counts"] = "  /fqp stats Imprimer la base de données et le nombre de broches",
        ["  /fqp available List quests that should pin on this map"] = "  /fqp available Liste les quêtes qui devraient être épinglées sur cette carte",
        ["  /fqp apis     Print which Forever map/quest APIs are present"] = "  /fqp apis Imprimer quelles API de carte/quête Forever sont présentes",
        ["  /fqp why <id> Show why a quest is pinned or hidden"] = "  /fqp why <id> Afficher pourquoi une quête est épinglée ou masquée",
        ["  /fqp wipe     Reset options (only needed after an older broken build)"] = "  Options de réinitialisation /fqp wipe (nécessaire uniquement après une ancienne version cassée)",
