        ["Only auto-accept quests within the level range around your level. Unknown quest levels are left for manual acceptance."] = "僅自動接受在您等級附近等級範圍內的任務。未知的任務等級留給手動接受。",
        ["Auto-accept quest levels: yours %+d to %+d"] = "自動接受的任務等級：你的%+d 到 %+d",
        ["Don't auto-accept grey quests"] = "不自動接受灰色任務",
        ["Skip quests the game shows as grey (trivial) for your level. You can still accept them manually."] = "跳過遊戲中對你的等級顯示為灰色（無意義）的任務。你仍可以手動接受它們。",
        ["Accept quests automatically when you talk to an NPC. Hold Shift to skip."] = "與 NPC 交談時自動接受任務。按住 Shift 鍵可跳過。",
        ["Auto-turn in quests"] = "自動回報任務",
        ["Turn in completed quests automatically. Does not pick when there are multiple rewards. Hold Shift to skip."] = "自動上交已完成的任務。當有多個獎勵時不選擇。按住 Shift 鍵可跳過。",
        ["Makes the default objective tracker transparent while you are in combat and restores its opacity afterward. Keeps your manual collapse setting."] = "在戰鬥中使預設目標追蹤器透明，然後恢復其不透明度。保留您的手動折疊設定。",
