        ["  /fqp npctooltip Toggle quest accept and ready turn-in lines on NPC mouseover"] = "  /fqp npctooltip 切換 NPC 提示中的可接取及可回報任務",
        ["  /fqp nameplates Toggle quest icons on nameplates (on by default)"] = "  /fqp nameplates 切換姓名板上的任務圖示（預設開啟）",
