        ["Allow clicks on quest start pins to track them on world and continent maps. When off, tooltips remain available, but Shift-click hiding is unavailable on those maps."] = "允許點擊任務開始標記以在世界和大陸地圖上追蹤它們。關閉後，工具提示仍然可用，但在這些地圖上按住 Shift 鍵單擊隱藏不可用。",
