        ["Library book pickup quests. Off hides their pins, NPC tooltips, nameplate icons, and auto-accept."] = "도서관 책 수집 퀘스트입니다. 끄면 핀, NPC 툴팁, 이름표 아이콘 및 자동 수락이 숨겨집니다.",
