        ["Profession-restricted quest starts, except class and dungeon / raid quests."] = "직업, 던전 및 공격대 퀘스트를 제외한 전문 기술 전용 퀘스트 시작 위치.",
        ["Blue start markers for repeatable, daily, weekly, and monthly quests."] = "반복, 일일, 주간 및 월간 퀘스트의 시작 위치를 파란색으로 표시합니다.",
        ["Group nearby spawn points into one pin. Hovering shows the spawn count and every location on the map. When off, show one pin per quest."] = "근처의 생성 지점을 하나의 핀으로 그룹화합니다. 마우스를 올리면 스폰 횟수와 지도의 모든 위치가 표시됩니다. 꺼져 있으면 퀘스트당 하나의 핀을 표시합니다.",
