        ["Show Blizzard's floating destination marker and distance for the tracked quest or map pin. This changes the game's shared navigation setting."] = "Blizzard의 떠다니는 목적지 마커와 추적된 퀘스트 또는 지도 핀의 거리를 표시합니다. 그러면 게임의 공유 탐색 설정이 변경됩니다.",
        ["Show in-world destination marker"] = "세계 내 목적지 마커 표시",
