        ["|cffffd100Forever Quest Pins:|r Hid %d quest(s). Use Reset hidden quest pins in options or /fqp unhide to restore."] = "|cffffd100Forever Quest Pins:|r %d 퀘스트를 숨겼습니다. 옵션에서 숨겨진 퀘스트 핀 재설정을 사용하거나 /fqp unhide를 사용하여 복원하세요.",
        ["Auto-accept quests"] = "퀘스트 자동 수락",
