        ["Turn in completed quests automatically. Does not pick when there are multiple rewards. Hold Shift to skip."] = "완료된 퀘스트를 자동으로 제출하세요. 보상이 여러 개인 경우에는 선택하지 않습니다. 건너뛰려면 Shift를 누르세요.",
        ["Makes the default objective tracker transparent while you are in combat and restores its opacity afterward. Keeps your manual collapse setting."] = "전투 중에 기본 목표 추적기를 투명하게 만들고 나중에 불투명도를 복원합니다. 수동 축소 설정을 유지합니다.",
