        ["Show every quest pin you hid with Shift-click on this character. Other characters keep their hidden pins."] = "이 캐릭터에서 Shift 클릭으로 숨긴 모든 퀘스트 핀을 표시합니다. 다른 캐릭터의 숨긴 핀은 유지됩니다.",
