        ["  /fqp on       Enable quest-start pins"] = "  /fqp on 퀘스트 시작 핀 활성화",
        ["Blizzard does not allow a map pin in this zone."] = "Blizzard는 이 구역에 지도 핀을 허용하지 않습니다.",
        ["Blizzard Map Pins are unavailable on this client. TomTom can be selected in options."] = "이 클라이언트에서는 Blizzard 지도 핀을 사용할 수 없습니다. TomTom는 옵션에서 선택 가능합니다.",
        ["TomTom is not loaded. Choose Blizzard Map Pins or enable TomTom."] = "TomTom가 로드되지 않았습니다. Blizzard 지도 핀을 선택하거나 TomTom를 활성화하세요.",
        ["Commands:"] = "명령:",
        ["Blizzard quest tracking is unavailable on this client."] = "이 클라이언트에서는 Blizzard 퀘스트 추적을 사용할 수 없습니다.",
        ["  /fqp track <id> Track a quest start, objective, or turn-in"] = "  /fqp track <id> 퀘스트 시작, 목표 또는 완료 추적",
        ["  /fqp trivial  Toggle low-level/trivial pins (off by default)"] = "  /fqp trivial 낮은 수준/사소한 핀 토글(기본적으로 꺼져 있음)",
        ["  /fqp accept   Toggle auto-accept quests"] = "  /fqp accept 자동 수락 퀘스트 전환",
        ["  /fqp turnin   Toggle auto-turn in quests"] = "  /fqp turnin   퀘스트 자동 제출 켜기 또는 끄기",
        ["  /fqp wareffort Toggle AQ war effort pins in capitals (off by default)"] = "  /fqp wareffort 대도시의 AQ 전쟁 물자 퀘스트 핀 켜기 또는 끄기 (기본값: 꺼짐)",
        ["  /fqp wareffort always Always show AQ war effort pins"] = "  /fqp wareffort always AQ 전쟁 물자 표시를 항상 표시",
        ["  /fqp repeatable Toggle repeatable quest pins (on by default)"] = "  /fqp repeatable 반복 가능한 퀘스트 핀 전환(기본적으로 켜져 있음)",
        ["  /fqp books    Toggle collectible book quest pins (off by default)"] = "  /fqp books    수집 가능한 책 퀘스트 핀 전환(기본적으로 꺼져 있음)",
        ["  /fqp seasonal Toggle holiday/seasonal pins (off by default)"] = "  /fqp seasonal 휴일/계절 핀 전환(기본적으로 꺼져 있음)",
        ["  /fqp npctooltip Toggle quest accept and ready turn-in lines on NPC mouseover"] = "  /fqp npctooltip NPC 툴팁의 수락 가능 및 완료 가능 퀘스트 표시 켜기 또는 끄기",
        ["  /fqp nameplates Toggle quest icons on nameplates (on by default)"] = "  /fqp nameplates 이름표의 퀘스트 아이콘 표시 켜기 또는 끄기 (기본 켜짐)",
        ["  /fqp nameplatedebug Print visible nameplate icon state"] = "  /fqp nameplatedebug 표시 중인 이름표 아이콘 상태 출력",
        ["Nameplates module not loaded."] = "이름표 모듈이 로드되지 않았습니다.",
        ["  /fqp unhide <id|all> Restore one or all hidden quest pins"] = "  /fqp unhide <id|all> 숨겨진 퀘스트 핀 하나 또는 모두 복원",
        ["  /fqp trivial <%d-%d> Hide quests this many levels below you (default %d)"] = "  /fqp trivial <%d-%d> 이만큼 낮은 레벨의 퀘스트 숨기기(기본값 %d)",
        ["  /fqp debug    Toggle debug tooltips and chat diagnostics"] = "  /fqp debug 디버그 툴팁 및 채팅 진단 전환",
        ["  /fqp spawns   Toggle grouped spawn pins (on by default)"] = "  /fqp spawns 그룹화된 스폰 핀 토글(기본적으로 켜져 있음)",
        ["  /fqp highlevel <%d-%d> Hide quests this many levels above you (default %d means show all)"] = "  /fqp highlevel <%d-%d> 이만큼 높은 레벨의 퀘스트를 숨깁니다. (기본 %d는 모두 표시를 의미합니다.)",
        ["  /fqp hidden   List quest pins hidden with Shift-click on this character"] = "  /fqp hidden 이 캐릭터에서 Shift 클릭으로 숨긴 퀘스트 핀 목록 표시",
        ["  /fqp available List quests that should pin on this map"] = "  /fqp available 이 지도에 고정되어야 하는 퀘스트 목록",
        ["  /fqp stats    Print database and pin counts"] = "  /fqp stats 인쇄 데이터베이스 및 핀 수",
        ["  /fqp refresh  Rebuild pins on the current map"] = "  /fqp refresh 현재 지도에서 핀을 재구성합니다.",
        ["  /fqp settings Print saved option values (debug)"] = "  /fqp settings 저장된 옵션 값 인쇄(디버그)",
        ["Pins enabled."] = "핀이 활성화되었습니다.",
        ["Show repeatable quests"] = "반복 가능한 퀘스트 표시",
        ["Show trivial quests"] = "사소한 퀘스트 표시",
        ["NPC quest tooltips"] = "NPC 퀘스트 툴팁",
        ["Pins disabled."] = "핀이 비활성화되었습니다.",
        ["  /fqp apis     Print which Forever map/quest APIs are present"] = "  Forever 지도/퀘스트 API가 존재하는 /fqp apis 인쇄",
        ["Low-level pins: hiding quests %d+ levels below you."] = "낮은 레벨 핀: 자신보다 %d레벨 이상 낮은 퀘스트를 숨깁니다.",
        ["  /fqp why <id> Show why a quest is pinned or hidden"] = "  /fqp why <id> 퀘스트가 고정되거나 숨겨진 이유 표시",
        ["  /fqp wipe     Reset options (only needed after an older broken build)"] = "  /fqp wipe 재설정 옵션(이전의 손상된 버전 이후에만 필요함)",
        ["Low-level pins are currently shown. Type /fqp trivial to hide them."] = "현재 낮은 수준의 핀이 표시됩니다. 숨기려면 /fqp trivial를 입력하세요.",
        ["Showing quests at every level above you."] = "당신 위의 모든 레벨에서 퀘스트를 표시합니다.",
        ["Close the game completely, then delete:"] = "게임을 완전히 종료한 후 다음을 삭제하세요.",
        ["  (and the .bak next to each)"] = "  (그리고 각각 옆에 .bak가 있음)",
        ["Show seasonal/holiday pins"] = "계절/휴일 핀 표시",
        ["Hiding quests %d+ levels above you."] = "자신보다 %d레벨 이상 높은 퀘스트를 숨깁니다.",
        ["Restored %d hidden quest pin(s)."] = "%d 숨겨진 퀘스트 핀을 복원했습니다.",
        ["In-memory options reset to defaults."] = "메모리 내 옵션이 기본값으로 재설정됩니다.",
        ["Only needed if you used a 0.1.10–0.1.16 build that left empty SavedVariables."] = "SavedVariables가 비어 있는 0.1.10–0.1.16 버전을 사용한 경우에만 필요합니다.",
        ["Refreshed."] = "새로 고침.",
        ["Then start the client. New installs do not need this."] = "그런 다음 클라이언트를 시작하십시오. 새로 설치하는 경우에는 이것이 필요하지 않습니다.",
        ["Unknown command. Type /fqp help"] = "알 수 없는 명령입니다. /fqp help를 입력하세요",
        ["Usage: /fqp why <questID>"] = "용법: /fqp why <questID>",
        ["  /fqp unhide <id> or /fqp unhide all to restore"] = "  /fqp unhide <id> 또는 /fqp unhide all 복원",
        ["No viewed map. Open the world map first."] = "본 지도가 없습니다. 먼저 세계지도를 열어보세요.",
        [" is not in the quest database."] = " 퀘스트 데이터베이스에 없습니다.",
        ["Usage: /fqp unhide <id> or /fqp unhide all"] = "사용법: /fqp unhide <id> 또는 /fqp unhide all",
        ["Quest %d is not hidden on this character."] = "이 캐릭터에는 퀘스트 %d가 숨겨져 있지 않습니다.",
        ["No hidden quest pins on this character."] = "이 캐릭터에는 숨겨진 퀘스트 핀이 없습니다.",
        ["When off, clicks pass through quest start pins to the map. Tooltips remain available, but Shift-click hiding is unavailable. By default, tracking is available on zone maps."] = "꺼져 있으면 클릭이 퀘스트 시작 핀을 통해 지도로 전달됩니다. 도구 설명은 계속 사용할 수 있지만 Shift 키를 누른 채 클릭 숨기기는 사용할 수 없습니다. 기본적으로 구역 지도에서는 ​​추적이 가능합니다.",
        ["Allow clicks on quest start pins to track them on world and continent maps. When off, tooltips remain available, but Shift-click hiding is unavailable on those maps."] = "퀘스트 시작 핀을 클릭하면 세계 및 대륙 지도에서 추적할 수 있습니다. 끄면 툴팁을 계속 사용할 수 있지만 해당 맵에서는 Shift 키를 누른 채로 숨길 수 없습니다.",
        ["Restored quest %d."] = "복원된 퀘스트 %d.",
        ["  hidden quest pins on this character: %d"] = "  이 캐릭터의 숨겨진 퀘스트 핀: %d",
