        ["  /fqp chatlinks Toggle clickable Questie chat links (on by default)"] = "  /fqp chatlinks Questie 채팅 링크 클릭 가능 여부 전환 (기본값: 켜짐)",
        ["  /fqp finder  Open Quest Finder"] = "  /fqp finder  Quest Finder 열기",
        ["  /fqp finderdebug Print Quest Finder counts and active filters"] = "  /fqp finderdebug Quest Finder 개수와 활성 필터 출력",
        ["  /fqp finderreset Reset Quest Finder to the screen center"] = "  /fqp finderreset Quest Finder를 화면 중앙으로 재설정",
        ["  /fqp options Open addon settings"] = "  /fqp options 애드온 설정 열기",
        ["  /fqp pvp      Toggle PvP quest pins (off by default)"] = "  /fqp pvp      PvP 퀘스트 핀 켜기 또는 끄기 (기본값: 꺼짐)",
        ["  /fqp setup   Open the setup guide"] = "  /fqp setup   설정 안내 열기",
        ["  /fqp taint    List Blizzard fields tainted by an addon (debug)"] = "  /fqp taint    애드온에 의해 오염된 Blizzard 필드 목록 (디버그)",
        ["  /fqp unexplored Toggle quest pins in unexplored areas (on by default)"] = "  /fqp unexplored 탐험하지 않은 지역의 퀘스트 핀 켜기 또는 끄기 (기본값: 켜짐)",
        ["%d pre-quests"] = "선행 퀘스트 %d개",
        ["%s starts inside the dungeon, so a map pin is not available."] = "%s은(는) 던전 안에서 시작하므로 지도 핀을 사용할 수 없습니다.",
        ["Abandon it from the quest log to set a waypoint to the breadcrumb."] = "안내 퀘스트로 웨이포인트를 설정하려면 퀘스트 로그에서 해당 퀘스트를 포기하세요.",
