        ["Choose Options"] = "옵션 선택",
        ["Choose another zone or check Map pins settings."] = "다른 구역을 선택하거나 지도 핀 설정을 확인하세요.",
        ["Choose what works for you. You can change these later in the addon options."] = "원하는 방식을 선택하세요. 나중에 애드온 옵션에서 변경할 수 있습니다.",
