        ["Leads to %s"] = "%s(으)로 이어짐",
        ["Leads to %s."] = "%s(으)로 이어집니다.",
        ["Left-click: Quest Finder"] = "왼쪽 클릭: Quest Finder",
        ["Level %s"] = "레벨 %s",
        ["Lists all breadcrumbs for the zone, including completed and in-log breadcrumbs."] = "완료한 안내 퀘스트와 로그에 있는 안내 퀘스트를 포함하여 해당 구역의 모든 안내 퀘스트를 나열합니다.",
        ["Lists every Loremaster quest assigned to the zone, including quests in your log, chain-locked quests, and quests that start in other zones."] = "로그에 있는 퀘스트, 연계로 잠긴 퀘스트, 다른 구역에서 시작하는 퀘스트를 포함하여 해당 구역에 할당된 모든 이야기꾼 퀘스트를 나열합니다.",
        ["Lists every dungeon quest, including completed and unavailable quests."] = "완료한 퀘스트와 수락할 수 없는 퀘스트를 포함하여 모든 던전 퀘스트를 나열합니다.",
        ["Loremaster"] = "이야기꾼",
