        ["No map location is available for this quest."] = "이 퀘스트의 지도 위치를 사용할 수 없습니다.",
        ["No quests match this filter."] = "이 필터에 맞는 퀘스트가 없습니다.",
        ["No start map"] = "시작 지도 없음",
        ["No waypoint is available for this quest."] = "이 퀘스트의 웨이포인트를 사용할 수 없습니다.",
        ["Not available to your class."] = "직업에 해당하지 않습니다.",
