        ["Library book pickup quests. Off hides their pins, NPC tooltips, nameplate icons, and auto-accept."] = "Задания на сбор книг из библиотеки. Если выключено, скрываются их значки, подсказки NPC, значки на табличках имён и автопринятие.",
