        ["TomTom (optional addon)"] = "TomTom (дополнительный аддон)",
        ["Quest automation"] = "Автоматизация квестов",
        ["Hold Shift at an NPC to skip automation once."] = "Удерживайте Shift у NPC, чтобы один раз пропустить автоматизацию.",
        ["Limit auto-accept quest level"] = "Ограничить уровень автоматического принятия квеста",
        ["Only auto-accept quests within the level range around your level. Unknown quest levels are left for manual acceptance."] = "Автоматически принимаются только квесты в диапазоне уровней вокруг вашего уровня. Неизвестные уровни квестов оставлены для принятия вручную.",
        ["Auto-accept quest levels: yours %+d to %+d"] = "Уровни автоматически принимаемых квестов: ваш %+d до %+d",
        ["Don't auto-accept grey quests"] = "Не принимать серые квесты автоматически",
        ["Skip quests the game shows as grey (trivial) for your level. You can still accept them manually."] = "Пропускает квесты, которые игра показывает серыми (тривиальными) для вашего уровня. Их по-прежнему можно принять вручную.",
        ["Show in-world destination marker"] = "Показать маркер пункта назначения в мире",
        ["|cffffd100Forever Quest Pins:|r Hid %d quest(s). Use Reset hidden quest pins in options or /fqp unhide to restore."] = "|cffffd100Forever Quest Pins:|r Спрятаны квесты %d. Используйте «Сбросить скрытые метки квеста» в настройках или /fqp unhide для восстановления.",
        ["Accept quests automatically when you talk to an NPC. Hold Shift to skip."] = "Принимайте квесты автоматически, когда разговариваете с NPC. Удерживайте Shift, чтобы пропустить.",
        ["Makes the default objective tracker transparent while you are in combat and restores its opacity afterward. Keeps your manual collapse setting."] = "Делает индикатор целей по умолчанию прозрачным, пока вы находитесь в бою, и впоследствии восстанавливает его непрозрачность. Сохраняет настройку свертывания вручную.",
        ["%d hidden on this character. Shift-click a map pin to hide it."] = "%d скрыт у этого персонажа. Удерживая клавишу Shift, щелкните метку на карте, чтобы скрыть ее.",
        ["Show quest IDs, NPC IDs, map coordinates, and pin-parent diagnostics on hover."] = "Покажите идентификаторы квестов, идентификаторы NPC, координаты карты и диагностику родительских контактов при наведении курсора мыши.",
        ["Debug tooltips"] = "Подсказки отладки",
        ["Auto-turn in quests"] = "Автоматическая сдача заданий",
        ["Turn in completed quests automatically. Does not pick when there are multiple rewards. Hold Shift to skip."] = "Сдавайте выполненные квесты автоматически. Не выбирает, если наград несколько. Удерживайте Shift, чтобы пропустить.",
        ["Show every quest pin you hid with Shift-click on this character. Other characters keep their hidden pins."] = "Показывает все метки заданий, скрытые этим персонажем с помощью Shift и щелчка. Скрытые метки других персонажей сохраняются.",
        ["Quest"] = "Квест",
        ["Quest giver NPC "] = "NPC, дающий квесты ",
        ["%d possible spawn locations"] = "%d возможные места появления",
        ["Copy Wowhead URL"] = "Скопировать URL-адрес Wowhead",
        ["Copy Wowhead URL\nPress Cmd+C or Ctrl+C to copy the selected link."] = "Скопировать URL-адрес Wowhead\nНажмите Cmd+C или Ctrl+C, чтобы скопировать выбранную ссылку.",
        ["TomTom is not loaded. Choose Blizzard Map Pins or enable TomTom."] = "TomTom не загружен. Выберите отметки на карте Blizzard или включите TomTom.",
        ["Blizzard quest tracking is unavailable on this client."] = "В этом клиенте отслеживание квестов Blizzard недоступно.",
        ["Commands:"] = "Команды:",
        ["No quest location is available yet."] = "Место квеста пока недоступно.",
        ["Blizzard does not allow a map pin in this zone."] = "Blizzard не позволяет размещать метки на карте в этой зоне.",
        ["  /fqp track <id> Track a quest start, objective, or turn-in"] = "  /fqp track <id> Отслеживать начало квеста, цель или сдачу.",
        ["  /fqp off      Disable quest-start pins"] = "  /fqp off Отключить значки начала квеста.",
        ["  /fqp trivial  Toggle low-level/trivial pins (off by default)"] = "  /fqp trivial Переключение низкоуровневых/тривиальных выводов (по умолчанию отключено)",
        ["  /fqp trivial <%d-%d> Hide quests this many levels below you (default %d)"] = "  /fqp trivial <%d-%d> Скрыть задания на указанное число уровней ниже вашего (по умолчанию %d)",
        ["  /fqp highlevel <%d-%d> Hide quests this many levels above you (default %d means show all)"] = "  /fqp highlevel <%d-%d> Скрыть задания на указанное число уровней выше вашего (значение по умолчанию %d показывает все)",
        ["  /fqp repeatable Toggle repeatable quest pins (on by default)"] = "  /fqp repeatable Переключить значки повторяющихся квестов (включено по умолчанию)",
        ["  /fqp books    Toggle collectible book quest pins (off by default)"] = "  /fqp books    Переключить значки заданий на коллекционные книги (выключено по умолчанию)",
        ["Hide quest tracker in combat"] = "Скрыть трекер квестов в бою",
        ["  /fqp seasonal Toggle holiday/seasonal pins (off by default)"] = "  /fqp seasonal Переключить праздничные/сезонные значки (по умолчанию отключено)",
        ["  /fqp wareffort Toggle AQ war effort pins in capitals (off by default)"] = "  /fqp wareffort Включить или выключить метки военных приготовлений AQ в столицах (по умолчанию выключено)",
        ["  /fqp wareffort always Always show AQ war effort pins"] = "  /fqp wareffort always Всегда показывать метки военных приготовлений AQ",
        ["  /fqp accept   Toggle auto-accept quests"] = "  /fqp accept Переключить автоматическое принятие квестов",
        ["  /fqp turnin   Toggle auto-turn in quests"] = "  /fqp turnin   Включить или выключить автоматическую сдачу заданий",
        ["  /fqp npctooltip Toggle quest accept and ready turn-in lines on NPC mouseover"] = "  /fqp npctooltip Включить или выключить показ доступных и готовых к сдаче заданий в подсказках NPC",
        ["  /fqp nameplates Toggle quest icons on nameplates (on by default)"] = "  /fqp nameplates Включить или выключить значки заданий на табличках имён (включено по умолчанию)",
        ["  /fqp nameplatedebug Print visible nameplate icon state"] = "  /fqp nameplatedebug Показать состояние значков видимых табличек имён",
        ["Nameplates module not loaded."] = "Модуль табличек имён не загружен.",
        ["  /fqp hidden   List quest pins hidden with Shift-click on this character"] = "  /fqp hidden Показать метки заданий, скрытые этим персонажем с помощью Shift и щелчка",
        ["  /fqp unhide <id|all> Restore one or all hidden quest pins"] = "  /fqp unhide <id|all> Восстановить один или все скрытые значки квеста.",
        ["  /fqp debug    Toggle debug tooltips and chat diagnostics"] = "  /fqp debug Переключить подсказки отладки и диагностику чата",
        ["  /fqp refresh  Rebuild pins on the current map"] = "  /fqp refresh Перестроить булавки на текущей карте.",
        ["Reset hidden quest pins"] = "Сбросить скрытые метки квестов",
        ["Quest "] = "Квест ",
        ["  /fqp stats    Print database and pin counts"] = "  /fqp stats Показать количество записей в базе и меток",
        ["  /fqp settings Print saved option values (debug)"] = "  /fqp settings Распечатать сохраненные значения параметров (отладка)",
        ["Type /fqp for commands and troubleshooting."] = "Введите /fqp для команд и устранения неполадок.",
        ["  /fqp wipe     Reset options (only needed after an older broken build)"] = "  /fqp wipe Параметры сброса (нужны только после более старой сломанной версии)",
        ["Quest %d (title unavailable)"] = "Квест %d (название недоступно)",
        ["  /fqp why <id> Show why a quest is pinned or hidden"] = "  /fqp why <id> Показать, почему квест закреплен или скрыт.",
        ["  /fqp apis     Print which Forever map/quest APIs are present"] = "  /fqp apis Распечатать, какие API карт/квестов Forever присутствуют",
        ["  /fqp available List quests that should pin on this map"] = "  /fqp available Список квестов, которые следует закрепить на этой карте.",
        ["Shift-click to hide this marker."] = "Щелкните, удерживая клавишу Shift, чтобы скрыть этот маркер.",
        ["Click to track this quest start."] = "Нажмите, чтобы отследить начало этого квеста.",
        ["Pins enabled."] = "Пины включены.",
        ["Pins disabled."] = "Пины отключены.",
        ["Showing quests at every level above you."] = "Показаны квесты на каждом уровне выше вас.",
        ["TomTom could not create this waypoint."] = "TomTom не смог создать эту точку.",
        ["Hiding quests %d+ levels above you."] = "Скрытие квестов %d+ уровней над вами.",
        ["Low-level pins are currently shown. Type /fqp trivial to hide them."] = "Метки низкоуровневых заданий сейчас отображаются. Введите /fqp trivial, чтобы скрыть их.",
        ["Low-level pins: hiding quests %d+ levels below you."] = "Значки низкого уровня: скрытие квестов %d+ уровней ниже вас.",
        ["Show trivial quests"] = "Показывать низкоуровневые задания",
        ["NPC quest tooltips"] = "Подсказки квестов NPC",
        ["Show repeatable quests"] = "Показать повторяющиеся квесты",
        ["Show seasonal/holiday pins"] = "Показывать сезонные/праздничные значки",
        ["Close the game completely, then delete:"] = "Закройте игру полностью, затем удалите:",
        ["In-memory options reset to defaults."] = "Параметры в памяти сбрасываются до значений по умолчанию.",
        ["  (and the .bak next to each)"] = "  (и .bak рядом с каждым)",
        ["Blizzard Map Pins are unavailable on this client. TomTom can be selected in options."] = "Метки на карте Blizzard недоступны в этом клиенте. В настройках можно выбрать TomTom.",
        ["Hidden quest pins on this character (%d):"] = "Скрытые квестовые значки этого персонажа (%d):",
        ["  /fqp unhide <id> or /fqp unhide all to restore"] = "  /fqp unhide <id> или /fqp unhide all для восстановления",
        ["Restored %d hidden quest pin(s)."] = "Восстановлены скрытые квестовые значки %d.",
        ["Only needed if you used a 0.1.10–0.1.16 build that left empty SavedVariables."] = "Требуется только в том случае, если вы использовали версию 0.1.10–0.1.16, в которой SavedVariables остался пустым.",
        ["Refreshed."] = "Обновлён.",
        ["Unknown command. Type /fqp help"] = "Неизвестная команда. Введите /fqp help",
        ["Then start the client. New installs do not need this."] = "Затем запустите клиент. Для новых установок это не требуется.",
        ["Usage: /fqp why <questID>"] = "Использование: /fqp why <questID>",
        ["QuestieDB %s | %d quests | %d maps"] = "QuestieDB %s | %d квесты | Карты %d",
        ["Restored quest %d."] = "Восстановлен квест %d.",
        ["No hidden quest pins on this character."] = "У этого персонажа нет скрытых квестовых значков.",
        ["Usage: /fqp unhide <id> or /fqp unhide all"] = "Использование: /fqp unhide <id> или /fqp unhide all.",
        ["  hidden quest pins on this character: %d"] = "  скрытые квестовые значки для этого персонажа: %d",
        [" is not in the quest database."] = " его нет в базе данных квестов.",
        ["No viewed map. Open the world map first."] = "Нет просмотренной карты. Сначала откройте карту мира.",
        ["Quest %d is not hidden on this character."] = "Квест %d у этого персонажа не скрыт.",
        ["Allow clicks on quest start pins to track them on world and continent maps. When off, tooltips remain available, but Shift-click hiding is unavailable on those maps."] = "Разрешите нажимать на метки начала квестов, чтобы отслеживать их на картах мира и континентов. Если этот параметр отключен, всплывающие подсказки остаются доступными, но скрытие при нажатии клавиши Shift на этих картах недоступно.",
        ["  /fqp clear    Clear the addon waypoint"] = "  /fqp clear Очистить путевую точку аддона.",
        ["Track from world and continent maps"] = "Отслеживание с карт мира и континентов",
        ["  /fqp on       Enable quest-start pins"] = "  /fqp on Включить значки начала квеста",
        ["When off, clicks pass through quest start pins to the map. Tooltips remain available, but Shift-click hiding is unavailable. By default, tracking is available on zone maps."] = "Если этот параметр отключен, клики передаются через метки начала квеста на карту. Подсказки остаются доступными, но скрытие при нажатии клавиши Shift недоступно. По умолчанию отслеживание доступно на картах зон.",
        ["  /fqp spawns   Toggle grouped spawn pins (on by default)"] = "  /fqp spawns Переключить сгруппированные метки появления (по умолчанию включено)",
        -- Strings added in 1.2.1.
        ["  /fqp breadcrumb Toggle skipped-breadcrumb warnings"] = "  /fqp breadcrumb Переключить предупреждения о пропущенных квестах-указателях",
        ["  /fqp breadcrumbtest Preview the skipped-breadcrumb dialog"] = "  /fqp breadcrumbtest Предпросмотр окна пропущенного квеста-указателя",
        ["  /fqp chatlinks Toggle clickable Questie chat links (on by default)"] = "  /fqp chatlinks Переключить кликабельные ссылки на квесты в чате Questie (включено по умолчанию)",
        ["  /fqp finder  Open Quest Finder"] = "  /fqp finder  Открыть Quest Finder",
        ["  /fqp finderdebug Print Quest Finder counts and active filters"] = "  /fqp finderdebug Вывести счётчики Quest Finder и активные фильтры",
        ["  /fqp finderreset Reset Quest Finder to the screen center"] = "  /fqp finderreset Вернуть Quest Finder в центр экрана",
        ["  /fqp options Open addon settings"] = "  /fqp options Открыть настройки аддона",
        ["  /fqp pvp      Toggle PvP quest pins (off by default)"] = "  /fqp pvp      Переключить метки PvP-квестов (выключено по умолчанию)",
        ["  /fqp setup   Open the setup guide"] = "  /fqp setup   Открыть руководство по настройке",
        ["  /fqp taint    List Blizzard fields tainted by an addon (debug)"] = "  /fqp taint    Показать поля Blizzard, загрязнённые аддоном (отладка)",
        ["  /fqp unexplored Toggle quest pins in unexplored areas (on by default)"] = "  /fqp unexplored Переключить метки квестов в неизученных областях (включено по умолчанию)",
        ["%d pre-quests"] = "%d предварительных квестов",
