local trackerLocale = trackerTranslations[locale]
if not trackerLocale and locale == "esMX" then
    trackerLocale = trackerTranslations.esES
end
if trackerLocale then
    for key, value in pairs(trackerLocale) do
        translations[key] = value
    end
end
local interfaceLocale = interfaceTranslations[locale]
if not interfaceLocale and locale == "esMX" then
    interfaceLocale = interfaceTranslations.esES
end
if interfaceLocale then
    for key, value in pairs(interfaceLocale) do
        translations[key] = value
    end
end
if locale == "esMX" then
    for key, value in pairs(translations) do
        translations[key] = value:gsub("Todas las mazmorras", "Todos los calabozos")
            :gsub("todas las mazmorras", "todos los calabozos")
            :gsub("de la mazmorra", "del calabozo")
            :gsub("De la mazmorra", "Del calabozo")
            :gsub("una mazmorra", "un calabozo")
            :gsub("Una mazmorra", "Un calabozo")
            :gsub("esta mazmorra", "este calabozo")
            :gsub("Esta mazmorra", "Este calabozo")
            :gsub("otra mazmorra", "otro calabozo")
            :gsub("Otra mazmorra", "Otro calabozo")
            :gsub("la mazmorra", "el calabozo")
            :gsub("La mazmorra", "El calabozo")
            :gsub("mazmorras", "calabozos")
            :gsub("mazmorra", "calabozo")
            :gsub("Mazmorras", "Calabozos")
            :gsub("Mazmorra", "Calabozo")
    end
end
ns.L = setmetatable(translations, { __index = function(_, key) return key end })
